from course_model import *
c=chapter('html-media','HTML · conținut, media și formulare','Orar, galerie, subtitrări și controalele filtrării.','Introducere & HTML.pptx; views/pagini/index.ejs și produse.ejs','image')
def H(id,title,idea,example,explain,question,tests,slides='',solution=None,prompt=None):
 lesson(c,id,title,idea,example,explain,question,html(prompt or 'Construiește structura din exemplu.',solution or example,tests),slides)
H('html-images','Imaginea și alternativa textuală','`img` este un element fără tag de închidere. `src` arată fișierul, `alt` explică imaginea când aceasta nu poate fi văzută.',
 '<img src="cake.svg" alt="Chocolate cake" width="240" height="160">','Pentru o imagine decorativă folosești alt gol. O imagine informativă are nevoie de o descriere utilă, nu doar de cuvântul image.',q('Ce descrie imaginea pentru cine nu o vede?','alt','width','srcset'),[attr('img','src','cake.svg'),attr('img','alt','Chocolate cake'),attr('img','width','240')],'75–77')
H('html-figure','Imagine și legendă','`figure` grupează un conținut ilustrativ și explicația lui din `figcaption`. Nu orice imagine are nevoie de legendă, dar aceasta poate oferi context.',
 '<figure><img src="cake.svg" alt="Chocolate cake"><figcaption>Our chocolate cake</figcaption></figure>','figcaption este copil al aceluiași figure ca imaginea.',q('Ce element conține legenda?','figcaption','caption din orice table','source'),[exact('figure > figcaption','Our chocolate cake'),count('figure > img')],'50,76')
H('html-picture','Alege imaginea după ecran','`picture` permite surse alternative. Browserul alege primul `source` potrivit condiției media; `img` oferă varianta implicită și alternativa textuală.',
 '<picture>\n  <source media="(max-width: 600px)" srcset="cake-small.webp">\n  <img src="cake-large.webp" alt="Fruit cake">\n</picture>','Ordinea surselor contează. Calea mică și cea mare sunt două fișiere reale într-un proiect; aici verificăm structura.',q('Ce element oferă fallback-ul într-un picture?','img','title','br'),[attr('picture source','media','(max-width: 600px)'),attr('picture source','srcset','cake-small.webp'),attr('picture img','alt','Fruit cake')],'78–85')
H('html-srcset','srcset și sizes','`srcset` enumeră variante ale unei imagini. Descriptorul `w` reprezintă lățimea intrinsecă; `sizes` descrie spațiul pe care îl va ocupa imaginea în layout.',
 '<img src="cake-800.webp" srcset="cake-400.webp 400w, cake-800.webp 800w" sizes="(max-width: 600px) 100vw, 50vw" alt="Cake">','Browserul decide ce fișier este potrivit, ținând cont și de densitatea pixelilor. sizes nu este o comandă de redimensionare CSS.',q('Ce înseamnă 400w într-un srcset?','Imaginea sursă are lățimea intrinsecă de 400 pixeli','O durată de 400 secunde','Un preț de 400'),[attr('img','srcset','cake-400.webp 400w, cake-800.webp 800w'),attr('img','sizes','(max-width: 600px) 100vw, 50vw')],'78–85')
H('html-table','Un tabel are rânduri și celule','`table` organizează date, `tr` este un rând, `th` este o celulă de antet și `td` o valoare. Pentru orar folosim un tabel, nu pentru întregul layout.',
 '<table><caption>Opening hours</caption><thead><tr><th scope="col">Day</th><th scope="col">Hours</th></tr></thead><tbody><tr><td>Monday</td><td>09–18</td></tr></tbody></table>',
 'caption denumește tabelul; scope col leagă antetul de coloana sa. thead și tbody separă antetele de date.',q('Ce tag este o celulă de date?','td','tr','thead'),[exact('caption','Opening hours'),count('thead th[scope="col"]',2),exact('tbody tr td','Monday')],'68–74')
H('html-spans','Celule întinse pe coloane și rânduri','`colspan` ocupă mai multe coloane, `rowspan` mai multe rânduri. Celelalte celule trebuie numărate ținând cont de spațiul deja ocupat.',
 '<table><tbody><tr><th rowspan="2">Weekend</th><td>Saturday</td></tr><tr><td>Sunday</td></tr><tr><td colspan="2">Closed on holidays</td></tr></tbody></table>',
 'În al doilea rând nu mai adăugăm încă o celulă pentru Weekend: aceasta este deja ocupată de rowspan.',q('Ce atribut întinde o celulă pe două coloane?','colspan="2"','rowspan="2"','scope="2"'),[attr('th','rowspan','2'),attr('td[colspan]','colspan','2')],'71–74')
H('html-audio','Audio cu controale native','`audio controls` oferă controale de redare. `source` indică fișierul și tipul MIME. Alternativele sunt încercate în ordinea compatibilității.',
 '<audio controls><source src="welcome.mp3" type="audio/mpeg">Audio is not supported.</audio>','controls este un atribut boolean: prezența lui contează. controls="false" nu îl dezactivează.',q('Cum activezi controalele audio?','Prin prezența atributului controls','Prin controls="false"','Prin class="play" obligatoriu'),[count('audio[controls]'),attr('audio source','type','audio/mpeg')],'86–87')
H('html-video','Video și redare automată','`video` poate avea controls, poster, muted, loop și playsinline. Browserele restricționează autoplay, mai ales când există sunet.',
 '<video controls muted playsinline poster="cake.svg"><source src="chocolate.mp4" type="video/mp4"></video>',
 'Nu presupune că autoplay va funcționa peste tot. Oferă controale și nu porni sunet neașteptat. În proiect stilizăm și containerul video.',q('Ce atribut oprește sunetul inițial?','muted','poster','loop'),[count('video[controls][muted][playsinline]'),attr('video','poster','cake.svg'),attr('source','type','video/mp4')],'86–90')
H('html-captions','Subtitrări cu track și WebVTT','`track` leagă un fișier de subtitrări. `srclang` indică limba, `label` numele afișat în meniul video, iar `kind` tipul pistei.',
 '<video controls><source src="chocolate.mp4" type="video/mp4"><track src="captions-en.vtt" kind="captions" srclang="en" label="English" default></video>',
 'Un fișier VTT începe cu WEBVTT și conține intervale precum 00:00.000 --> 00:03.000. Folosește o cale .vtt și tip text/vtt când îl servești.',q('Ce format folosim pentru pista din exemplu?','WebVTT','Un fișier SQL','SCSS'),[attr('track','kind','captions'),attr('track','srclang','en'),attr('track','src','captions-en.vtt')],'88–90')
lesson(c,'html-vtt','Intervalele unei subtitrări','Subtitrarea are un moment de început și unul de sfârșit. Textul se afișează în acel interval, nu pentru tot videoclipul. Linia goală separă două intrări.',
 'WEBVTT\n\n00:00.000 --> 00:03.000\nChocolate!', 'Prima intrare se afișează în primele trei secunde. La finalul traseului vei găsi un fișier VTT complet în proiect.',q('Când apare textul din exemplu?','Între secunda 0 și secunda 3','Doar la finalul filmului','Permanent în meniul paginii'),text('Scrie antetul obligatoriu al unui fișier WebVTT.','WEBVTT'),'89–90')
H('html-iframe','Pagini încorporate și target','`iframe` încorporează un document. O legătură cu target egal cu name-ul iframe-ului poate încărca o altă resursă în aceeași zonă.',
 '<a href="recipe.html" target="recipeFrame">Recipe</a>\n<iframe name="recipeFrame" src="intro.html" title="Recipe video"></iframe>',
 'title descrie iframe-ul pentru accesibilitate. În proiect înlocuim taburile cu destinații alese explicit, fără un frameborder învechit.',q('Ce trebuie să corespundă cu target?','Atributul name al iframe-ului','Culoarea iframe-ului','Numele fișierului CSS'),[attr('a','target','recipeFrame'),attr('iframe','name','recipeFrame'),attr('iframe','title','Recipe video')],'91; secțiunea retete',prompt='Scrie legătura din exemplu. Iframe-ul este explicat aici; previzualizarea nu încarcă pagini externe.',solution='<a href="recipe.html" target="recipeFrame">Recipe</a>')
# Iframe-urile sunt eliminate din preview pentru siguranța exercițiilor HTML.
c['lessons'][-1]['task']['tests']=[attr('a','href','recipe.html'),attr('a','target','recipeFrame')]
H('html-details','FAQ fără JavaScript','`details` creează o zonă extensibilă; primul `summary` este eticheta pe care dai clic. Atributul open o arată desfăcută inițial.',
 '<details><summary>Do you deliver?</summary><p>Yes, locally.</p></details>', 'Acesta este mecanismul nativ folosit pentru întrebări frecvente. Nu ai nevoie de un onclick pentru a-l deschide.',q('Ce element este eticheta clicabilă?','summary','legend','caption'),[exact('details > summary','Do you deliver?'),exact('details p','Yes, locally.')],'92–93')
H('html-meter','O valoare într-un interval','`meter` reprezintă o măsurătoare cu limite cunoscute, de exemplu ocuparea locurilor. `progress` reprezintă progresul unei activități, nu aceeași noțiune.',
 '<meter min="0" max="100" value="30">30%</meter>\n<progress max="100" value="60">60%</progress>', 'min, max și value sunt valori numerice. Pentru un progres fără valoare cunoscută poți omite value.',q('Ce se potrivește pentru progresul unei încărcări?','progress','meter obligatoriu','time'),[attr('meter','value','30'),attr('meter','max','100'),attr('progress','value','60')],'94–95')
H('html-labels','Input și etichetă','Un `input` este un control de introducere. `label for` se leagă de id-ul controlului, astfel încât un clic pe etichetă să focalizeze câmpul.',
 '<label for="searchName">Product name</label>\n<input id="searchName" name="name" type="text" placeholder="Cake">', 'id leagă eticheta și JavaScript-ul; name este numele trimis într-un formular. Nu sunt obligatoriu identice.',q('Cu ce se potrivește atributul for al unui label?','Cu id-ul controlului','Cu textul placeholder','Cu extensia fișierului'),[attr('label','for','searchName'),attr('input#searchName','name','name'),attr('input','type','text')],'95; produse.ejs')
H('html-form','Formulare, metode și butoane','`form` grupează câmpuri. `action` indică destinația, `method` felul trimiterii. Un button din form trimite formularul implicit dacă nu îi specifici type.',
 '<form action="/products" method="get"><label for="query">Search</label><input id="query" name="q"><button type="submit">Search</button><button type="button">Reset filters</button></form>',
 'get pune câmpurile în query string. Un buton pentru o acțiune JavaScript obișnuită folosește type="button" pentru a evita trimiterea accidentală.',q('Ce type alegi pentru un buton care nu trimite formularul?','button','submit','form'),[attr('form','method','get'),attr('form','action','/products'),count('button[type="submit"]'),count('button[type="button"]')],'95; produse.ejs')
H('html-select','Alegere dintr-o listă','`select` conține opțiuni `option`. Textul este eticheta, iar value este valoarea pe care o citește JavaScript. `selected` alege varianta inițială.',
 '<label for="category">Category</label><select id="category"><option value="all" selected>All</option><option value="cake">Cakes</option></select>',
 'În filtre folosim all pentru a indica lipsa unei restricții; nu este un cuvânt rezervat HTML.',q('Ce citim ca valoare selectată?','value','Doar textul din label','Atributul for'),[attr('select','id','category'),attr('option[selected]','value','all'),count('select option',2)],'produse.ejs')
H('html-radio','Radio și checkbox','Controalele radio cu același name formează o alegere unică. Checkbox-urile permit selecții independente. checked înseamnă selectat.',
 '<fieldset><legend>Calories</legend><label><input type="radio" name="calories" value="low">Low</label><label><input type="radio" name="calories" value="all" checked>All</label></fieldset><label><input type="checkbox" class="cart-choice" value="1">Add to cart</label>',
 'Același name unește radio-urile; în coș avem câte un checkbox pentru fiecare produs. fieldset și legend descriu grupul.',q('Ce face ca două radio-uri să aparțină aceluiași grup?','Același name','Același text vizibil','Aceeași culoare'),[count('input[type="radio"][name="calories"]',2),attr('input[type="radio"][checked]','value','all'),count('input[type="checkbox"].cart-choice')],'produse.ejs')
H('html-range','Intervale, valori și validare de bază','Un input range oferă un cursor între min și max. `required`, `minlength` și alte atribute pot valida date în browser, dar serverul trebuie să verifice separat ce primește.',
 '<label for="minPrice">Minimum price</label><input id="minPrice" type="range" min="0" max="100" value="0" step="5"><output for="minPrice">0</output>',
 'output poate afișa valoarea; JavaScript o va actualiza la evenimentul input. Validarea din browser poate fi ocolită.',q('Unde este definită limita superioară a cursorului?','max','value','step'),[attr('#minPrice','type','range'),attr('#minPrice','min','0'),attr('#minPrice','max','100'),attr('#minPrice','step','5')],'produse.ejs')
lesson(c,'html-validation','Validare și compatibilitate','Un browser poate repara HTML invalid și totuși să afișeze ceva. Validatorul semnalează probleme structurale. Taguri învechite precum font și center trebuie înlocuite cu HTML semantic și CSS.',
 '<!-- Use semantic HTML; style it with CSS. -->\n<p class="notice">Fresh today</p>', 'Testează pagina în mai multe browsere și cu tastatura. Nici validatorul, nici o captură reușită nu demonstrează singure accesibilitatea completă.',q('O pagină care arată bine este automat HTML valid?','Nu; browserul poate repara erori','Da, fără excepții','Da, dacă are dark mode'),html('Înlocuiește center și font cu un paragraf notice.','<p class="notice">Fresh today</p>',[exact('p.notice','Fresh today'),absent('center'),absent('font')],'<center><font>Fresh today</font></center>'),'96–104')

m=chapter('mathml','MathML · fiecare piesă a formulei','Tokeni, fracții, puteri, radicali, tabele și grupare.','MathML si CSS.pptx, 3–22','math')
for id,title,idea,example,tests,quiz in [
 ('tokens','Identificatori, numere și operatori','În interiorul math, mi este un identificator, mn un număr și mo un operator. Nu construi întreaga formulă ca un singur șir într-un p.','<math><mi>x</mi><mo>+</mo><mn>2</mn></math>',[exact('math mi','x'),exact('math mo','+'),exact('math mn','2')],q('Ce tag reprezintă un operator?','mo','mi','mn')),
 ('fraction','Numărător și numitor','mfrac are doi copii: numărătorul și numitorul. Dacă unul dintre ei are mai multe piese, îl grupezi cu mrow.','<math><mfrac><mrow><mi>x</mi><mo>+</mo><mn>1</mn></mrow><mn>2</mn></mfrac></math>',[exact('mfrac > mrow','x+1'),exact('mfrac > mn','2')],q('Ce este al doilea copil din mfrac?','Numitorul','Exponentul','Titlul formulei')),
 ('scripts','Puteri și indici matematici','msup are baza și exponentul; msub are baza și indicele. msubsup le combină folosind trei copii.','<math><msup><mi>x</mi><mn>2</mn></msup><mo>+</mo><msub><mi>a</mi><mn>1</mn></msub></math>',[exact('msup > mi','x'),exact('msup > mn','2'),exact('msub > mn','1')],q('Ce pereche aparține lui msup?','Bază și exponent','Numărător și numitor','Antet și subsol')),
 ('roots','Radical și rădăcină de ordin n','msqrt creează radical pătrat. mroot are expresia de sub radical și indicele rădăcinii.','<math><msqrt><mi>x</mi></msqrt><mo>+</mo><mroot><mi>y</mi><mn>3</mn></mroot></math>',[exact('msqrt mi','x'),exact('mroot > mi','y'),exact('mroot > mn','3')],q('Ce folosești pentru rădăcina cubică?','mroot cu indice 3','msqrt cu title 3','mfrac')),
 ('matrix','Rânduri și celule în formule','mtable grupează rânduri mtr; fiecare rând conține celule mtd. Structura permite alinierea sistemelor și a matricilor.','<math><mtable><mtr><mtd><mn>1</mn></mtd><mtd><mn>2</mn></mtd></mtr></mtable></math>',[count('mtable mtr',1),count('mtr mtd',2)],q('Ce element este celula unei tabele MathML?','mtd','td în orice context','mrow obligatoriu')),
]:
 lesson(m,'math-'+id,title,idea,example,'Ordinea și gruparea copiilor descriu structura matematică. Exemplul folosește MathML nativ; MathJax poate oferi procesare și compatibilitate suplimentară.',quiz,html('Construiește formula afișată în exemplu.',example,tests))
lesson(m,'math-display','MathJax, afișare și validare','MathML poate fi inline sau block. Prezentarea explică și MathJax, care se încarcă ca bibliotecă atunci când proiectul are nevoie de el. Aici formulele simple folosesc suportul nativ al browserului.',
 '<math display="block"><mi>x</mi><mo>=</mo><mn>2</mn></math>', 'Verifică formula în browser și structura ei. În traseu apar și mtext, mspace, mstyle, mpadded, mphantom, mover, munder, munderover și semantics în fișele detaliate ale sursei.',q('Ce alege afișarea formulei pe un rând propriu?','display="block"','type="sql"','href="math"'),html('Afișează formula x = 2 ca block.','<math display="block"><mi>x</mi><mo>=</mo><mn>2</mn></math>',[attr('math','display','block'),exact('math mo','=')]))
